procedure @@proc@@(p_n in number) is
  l_done number := 0;
begin
  for i in 1 .. p_n loop
    insert into @@tab@@ (id, @@col@@)
    values (i, sysdate);
    commit; -- @expect
    l_done := l_done + 1;
  end loop;
end @@proc@@;

procedure @@proc@@(p_max in number) is
  l_i number := 0;
  l_failed boolean;
begin
  while l_i < p_max loop
    l_failed := @@proc2@@(l_i);
    if l_failed then
      rollback; -- @expect
    end if;
    l_i := l_i + 1;
  end loop;
end @@proc@@;

procedure @@proc@@(p_flush in boolean, p_max in number) is
  l_n number := 0;
begin
  if p_flush then
    loop
      l_n := l_n + 1;
      @@proc2@@(l_n);
      commit; -- @expect
      exit when l_n >= p_max;
    end loop;
  end if;
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_skipped number := 0;
begin
  for i in 1 .. p_n loop
    begin
      @@proc2@@(i);
    exception
      when dup_val_on_index then
        commit; -- @expect
        l_skipped := l_skipped + 1;
    end;
  end loop;
  dbms_output.put_line(l_skipped);
end @@proc@@;

procedure @@proc@@(p_n in number) is
begin
  for i in 1 .. p_n loop
    declare
      l_val number;
    begin
      l_val := i * 2;
      @@proc2@@(l_val);
      commit; -- @expect
    end;
  end loop;
end @@proc@@;

