procedure @@proc@@(p_n in number) is
begin
  for i in 1 .. p_n loop
    insert into @@tab@@ (id, @@col@@)
    values (i, sysdate);
  end loop;
  commit;
end @@proc@@;

procedure @@proc@@(p_n in number) is
begin
  for i in 1 .. p_n loop
    savepoint sp_row;
    begin
      @@proc2@@(i);
    exception
      when dup_val_on_index then
        rollback to savepoint sp_row;
    end;
  end loop;
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_sum number := 0;
begin
  commit;
  for i in 1 .. p_n loop
    l_sum := l_sum + i;
  end loop;
  dbms_output.put_line(l_sum);
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_msg varchar2(100);
begin
  for i in 1 .. p_n loop
    -- we do not commit here, the caller commits at the end
    l_msg := 'COMMIT postponed for ' || i;
    dbms_output.put_line(l_msg);
  end loop;
end @@proc@@;

procedure @@proc@@(p_limit in number) is
  l_i number := 0;
begin
  while l_i < p_limit loop
    @@proc2@@(l_i);
    l_i := l_i + 1;
  end loop;
  rollback;
end @@proc@@;
